-- Migration : nouveautés de la plateforme (onglet Suggestions de l'espace
-- photographe, voir worker/src/changelog.js), et les premières entrées.
-- À appliquer une seule fois.

CREATE TABLE IF NOT EXISTS changelog (
  id           TEXT PRIMARY KEY,               -- chg_…
  published_at INTEGER NOT NULL,
  kind         TEXT NOT NULL DEFAULT 'feature', -- feature | improvement | shortcut | fix
  title_fr     TEXT NOT NULL,
  body_fr      TEXT NOT NULL DEFAULT '',
  title_en     TEXT NOT NULL DEFAULT '',
  body_en      TEXT NOT NULL DEFAULT '',
  title_nl     TEXT NOT NULL DEFAULT '',
  body_nl      TEXT NOT NULL DEFAULT '',
  link         TEXT NOT NULL DEFAULT '',        -- écran à essayer (#/relances…)
  feedback_id  TEXT NOT NULL DEFAULT '',        -- suggestion réalisée
  credit       INTEGER NOT NULL DEFAULT 1,      -- nommer son auteur
  created_at   INTEGER NOT NULL,
  updated_at   INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_changelog_published ON changelog(published_at);

-- Dernière visite des nouveautés (pastille de l'onglet Suggestions).
ALTER TABLE photographers ADD COLUMN changelog_seen_at INTEGER;

INSERT OR IGNORE INTO changelog (id, published_at, kind, title_fr, body_fr, title_en, body_en, title_nl, body_nl, link, feedback_id, credit, created_at, updated_at) VALUES ('chg_seed_17', 1794996000, 'feature', 'Relances automatiques et campagnes e-mail', 'Nouvel onglet Relances : toutes vos relances au même endroit, six nouvelles (sélection pas commencée, offre de bienvenue sur les tirages, un an déjà, demande d''avis…), des campagnes prêtes en trois langues, et ce qu''elles vous rapportent.', 'Automatic reminders and email campaigns', 'New Emails tab: all your reminders in one place, six new ones (selection not started, welcome offer on prints, one year already, review request…), ready-made campaigns in three languages, and what they bring in.', 'Automatische herinneringen en e-mailcampagnes', 'Nieuw tabblad Herinneringen: al je herinneringen op één plek, zes nieuwe (selectie niet begonnen, welkomstaanbod op afdrukken, al een jaar, vraag om een review…), kant-en-klare campagnes in drie talen, en wat ze opleveren.', '#/relances', '', 0, 1794996000, 1794996000);
INSERT OR IGNORE INTO changelog (id, published_at, kind, title_fr, body_fr, title_en, body_en, title_nl, body_nl, link, feedback_id, credit, created_at, updated_at) VALUES ('chg_seed_16', 1794995940, 'improvement', 'Fiche client complète', 'Sur chaque fiche : ses séances, ses factures (avec le PDF), ses règlements et ce qui reste à régler. Ce qui a été créé sans e-mail est rattaché au client par son nom.', 'Complete client record', 'On every record: their sessions, invoices (with the PDF), payments and what''s still due. Anything created without an email is linked to the client by name.', 'Volledige klantenfiche', 'Op elke fiche: de shoots, facturen (met pdf), betalingen en wat nog openstaat. Wat zonder e-mailadres werd aangemaakt, wordt via de naam aan de klant gekoppeld.', '#/clients', '', 0, 1794995940, 1794995940);
INSERT OR IGNORE INTO changelog (id, published_at, kind, title_fr, body_fr, title_en, body_en, title_nl, body_nl, link, feedback_id, credit, created_at, updated_at) VALUES ('chg_seed_15', 1794995880, 'feature', 'Holypixx en néerlandais', 'L''espace photographe, les galeries clients et leurs e-mails existent maintenant en néerlandais : choisissez « Nederlands » pour une galerie.', 'Holypixx in Dutch', 'The dashboard, client galleries and their emails are now available in Dutch: pick “Nederlands” for a gallery.', 'Holypixx in het Nederlands', 'De fotografenomgeving, de klantengalerijen en hun e-mails bestaan nu in het Nederlands: kies „Nederlands” voor een galerij.', '#/parametres', '', 0, 1794995880, 1794995880);
INSERT OR IGNORE INTO changelog (id, published_at, kind, title_fr, body_fr, title_en, body_en, title_nl, body_nl, link, feedback_id, credit, created_at, updated_at) VALUES ('chg_seed_14', 1794995820, 'feature', 'Lumi parle et écoute', 'Posez votre question à voix haute et écoutez la réponse : boutons micro et haut-parleur dans Lumi.', 'Lumi speaks and listens', 'Ask your question out loud and listen to the answer: microphone and speaker buttons in Lumi.', 'Lumi praat en luistert', 'Stel je vraag hardop en beluister het antwoord: microfoon- en luidsprekerknop in Lumi.', '', '', 0, 1794995820, 1794995820);
INSERT OR IGNORE INTO changelog (id, published_at, kind, title_fr, body_fr, title_en, body_en, title_nl, body_nl, link, feedback_id, credit, created_at, updated_at) VALUES ('chg_seed_13', 1794563760, 'shortcut', 'Un « i » à côté de chaque titre', 'Survolez-le pour le résumé de la page, cliquez pour son mode d''emploi pas à pas.', 'An “i” next to every title', 'Hover it for a summary of the page, click it for step-by-step help.', 'Een „i” naast elke titel', 'Ga erover voor een samenvatting van de pagina, klik voor de uitleg stap voor stap.', '', '', 0, 1794563760, 1794563760);
INSERT OR IGNORE INTO changelog (id, published_at, kind, title_fr, body_fr, title_en, body_en, title_nl, body_nl, link, feedback_id, credit, created_at, updated_at) VALUES ('chg_seed_12', 1794563700, 'feature', 'Lumi, votre guide', 'Une assistante qui répond à vos questions sur Holypixx, en bas à droite de chaque écran.', 'Lumi, your guide', 'An assistant that answers your questions about Holypixx, bottom right of every screen.', 'Lumi, je gids', 'Een assistente die je vragen over Holypixx beantwoordt, rechtsonder op elk scherm.', '', '', 0, 1794563700, 1794563700);
INSERT OR IGNORE INTO changelog (id, published_at, kind, title_fr, body_fr, title_en, body_en, title_nl, body_nl, link, feedback_id, credit, created_at, updated_at) VALUES ('chg_seed_11', 1794563640, 'feature', 'Modèles de contrat par type de séance', 'Préparez un contrat pour la grossesse, le mariage, la naissance, les mini-séances… il est proposé automatiquement selon la séance.', 'Contract templates by session type', 'Prepare a contract for maternity, weddings, newborns, mini sessions… it''s suggested automatically for each session.', 'Contractmodellen per type shoot', 'Maak een contract klaar voor zwangerschap, huwelijk, newborn, minishoots… het wordt automatisch voorgesteld per shoot.', '#/contrats', '', 0, 1794563640, 1794563640);
INSERT OR IGNORE INTO changelog (id, published_at, kind, title_fr, body_fr, title_en, body_en, title_nl, body_nl, link, feedback_id, credit, created_at, updated_at) VALUES ('chg_seed_10', 1794563580, 'feature', 'Suivi des séances', 'De la réservation à la livraison, une étape après l''autre : fiche client, contrat, rappel, liste de préparation, envoi de la galerie.', 'Session tracking', 'From booking to delivery, step by step: client record, contract, reminder, prep list, sending the gallery.', 'Opvolging van shoots', 'Van boeking tot levering, stap voor stap: klantenfiche, contract, herinnering, voorbereidingslijst, galerij versturen.', '#/reservations', '', 0, 1794563580, 1794563580);
INSERT OR IGNORE INTO changelog (id, published_at, kind, title_fr, body_fr, title_en, body_en, title_nl, body_nl, link, feedback_id, credit, created_at, updated_at) VALUES ('chg_seed_09', 1794563520, 'feature', 'Page de réservation seule', 'Vos clients réservent sans mini-site : un lien, un QR code, un bouton ou l''agenda intégré à votre propre site.', 'Standalone booking page', 'Clients book without a mini-site: a link, a QR code, a button or the calendar embedded in your own website.', 'Losse boekingspagina', 'Klanten boeken zonder minisite: een link, een QR-code, een knop of de agenda in je eigen website.', '#/reservations', '', 0, 1794563520, 1794563520);
INSERT OR IGNORE INTO changelog (id, published_at, kind, title_fr, body_fr, title_en, body_en, title_nl, body_nl, link, feedback_id, credit, created_at, updated_at) VALUES ('chg_seed_08', 1794563460, 'feature', 'Créneaux privés', 'Un lien secret pour qu''un client réserve un créneau rien que pour lui.', 'Private slots', 'A secret link so one client can book a slot just for them.', 'Privétijdsloten', 'Een geheime link zodat één klant een tijdslot voor zichzelf kan boeken.', '#/reservations', '', 0, 1794563460, 1794563460);
INSERT OR IGNORE INTO changelog (id, published_at, kind, title_fr, body_fr, title_en, body_en, title_nl, body_nl, link, feedback_id, credit, created_at, updated_at) VALUES ('chg_seed_07', 1794563400, 'shortcut', 'Holypixx sur l''écran d''accueil', 'Installez l''espace photographe comme une appli sur votre téléphone, tablette ou ordinateur : bouton « Installer l''appli ».', 'Holypixx on your home screen', 'Install the dashboard like an app on your phone, tablet or computer: “Install the app” button.', 'Holypixx op je beginscherm', 'Installeer de fotografenomgeving als een app op je telefoon, tablet of computer: knop „App installeren”.', '', '', 0, 1794563400, 1794563400);
INSERT OR IGNORE INTO changelog (id, published_at, kind, title_fr, body_fr, title_en, body_en, title_nl, body_nl, link, feedback_id, credit, created_at, updated_at) VALUES ('chg_seed_06', 1794563340, 'feature', 'Suggestions', 'Cet onglet : proposez une idée, suivez où elle en est, recevez la réponse.', 'Suggestions', 'This tab: share an idea, follow its progress, get the answer.', 'Suggesties', 'Dit tabblad: deel een idee, volg hoe ver het staat, krijg het antwoord.', '#/suggestions', '', 0, 1794563340, 1794563340);
INSERT OR IGNORE INTO changelog (id, published_at, kind, title_fr, body_fr, title_en, body_en, title_nl, body_nl, link, feedback_id, credit, created_at, updated_at) VALUES ('chg_seed_05', 1794476880, 'feature', 'Options payantes et relance des suppléments', 'Retouche avancée, clé USB, livraison express… cochées par le client dans sa galerie ; relance automatique des suppléments non réglés.', 'Paid options and extras reminders', 'Advanced retouching, USB stick, express delivery… ticked by clients in their gallery; automatic reminders for unpaid extras.', 'Betaalde opties en herinneringen voor extra''s', 'Geavanceerde retouche, usb-stick, express levering… aangevinkt door de klant in de galerij; automatische herinnering voor onbetaalde extra foto''s.', '', '', 0, 1794476880, 1794476880);
INSERT OR IGNORE INTO changelog (id, published_at, kind, title_fr, body_fr, title_en, body_en, title_nl, body_nl, link, feedback_id, credit, created_at, updated_at) VALUES ('chg_seed_04', 1794476820, 'shortcut', 'Textes d''accompagnement enregistrés', 'Vos mots d''accueil de galerie, enregistrés une fois et choisis dans un menu.', 'Saved welcome texts', 'Your gallery welcome notes, saved once and picked from a menu.', 'Bewaarde begeleidende teksten', 'Je welkomstwoorden voor galerijen, één keer bewaard en kiesbaar in een menu.', '', '', 0, 1794476820, 1794476820);
INSERT OR IGNORE INTO changelog (id, published_at, kind, title_fr, body_fr, title_en, body_en, title_nl, body_nl, link, feedback_id, credit, created_at, updated_at) VALUES ('chg_seed_03', 1794303960, 'improvement', 'Envois de photos en arrière-plan', 'Continuez à travailler pendant que vos photos s''envoient.', 'Photo uploads in the background', 'Keep working while your photos upload.', 'Foto''s uploaden op de achtergrond', 'Werk gewoon verder terwijl je foto''s uploaden.', '', '', 0, 1794303960, 1794303960);
INSERT OR IGNORE INTO changelog (id, published_at, kind, title_fr, body_fr, title_en, body_en, title_nl, body_nl, link, feedback_id, credit, created_at, updated_at) VALUES ('chg_seed_02', 1794303900, 'improvement', 'Suppléments réglés hors galerie', 'Facturation : les suppléments en attente, marqués réglés en espèces ou par virement, avec facture envoyée au client.', 'Extras paid outside the gallery', 'Billing: extras awaiting payment, marked as paid in cash or by transfer, with the invoice sent to the client.', 'Extra''s buiten de galerij betaald', 'Facturatie: openstaande extra''s, gemarkeerd als cash of via overschrijving betaald, met factuur naar de klant.', '#/facturation', '', 0, 1794303900, 1794303900);
INSERT OR IGNORE INTO changelog (id, published_at, kind, title_fr, body_fr, title_en, body_en, title_nl, body_nl, link, feedback_id, credit, created_at, updated_at) VALUES ('chg_seed_01', 1793699040, 'feature', 'Tirages sur les photos retouchées', 'La boutique propose les photos livrées en HD, imprimées depuis le fichier retouché.', 'Prints of your retouched photos', 'The shop offers the photos delivered in HD, printed from the retouched file.', 'Afdrukken van je geretoucheerde foto''s', 'De webshop biedt de in HD geleverde foto''s aan, afgedrukt vanaf het geretoucheerde bestand.', '#/boutique', '', 0, 1793699040, 1793699040);
